--- build_words.py ---
import os, re, json, html
from urllib.parse import unquote

d = 'site'
pages = {}      # filename -> parsed page
redirects = {}  # filename -> target filename

SKIP = {'index.html', 'sobre.html', 'contato.html'}

for f in sorted(os.listdir(d)):
    if not f.endswith('.html'):
        continue
    raw = open(os.path.join(d, f), encoding='utf-8').read()
    m = re.search(r'http-equiv="refresh"[^>]*url=([^">]+)', raw)
    if m:
        redirects[f] = unquote(m.group(1))
        continue
    if f in SKIP:
        continue
    t = re.search(r'<h1>(.*?)</h1>', raw)
    tema = re.search(r'class="tema">Tema: (.*?)<', raw)
    sec = {}
    for sm in re.finditer(r'<section id="(\w+)">(.*?)</section>', raw, re.S):
        sec[sm.group(1)] = [unquote(x) for x in re.findall(r'href="([^"]+\.html)"', sm.group(2))]
    pages[f] = {
        'word': html.unescape(t.group(1)).strip() if t else f[:-5],
        'tema': html.unescape(tema.group(1)).strip() if tema else 'sem tema',
        'sinonimos': sec.get('sinonimos', []),
        'analogas': sec.get('analogas', []),
    }

# resolve redirects (one hop should be enough, but loop to be safe)
def resolve(f):
    seen = set()
    while f in redirects and f not in seen:
        seen.add(f)
        f = redirects[f]
    return f

dropped = set()
words = {}  # canonical word -> {tema, sinonimos[], analogas[]}
for f, p in pages.items():
    entry = {'tema': p['tema'], 'sinonimos': [], 'analogas': []}
    for kind in ('sinonimos', 'analogas'):
        seen = []
        for tgt in p[kind]:
            rf = resolve(tgt)
            if rf not in pages:
                dropped.add(tgt)
                continue
            tw = pages[rf]['word']
            if tw != p['word'] and tw not in seen:
                seen.append(tw)
        entry[kind] = seen
    words[p['word']] = entry

# stats
pairs = set()
total_links = 0
for w, e in words.items():
    for kind in ('sinonimos', 'analogas'):
        for t in e[kind]:
            total_links += 1
            pairs.add(tuple(sorted((w, t))))
most = max(words, key=lambda w: len(words[w]['sinonimos']) + len(words[w]['analogas']))

result = {
    'words': len(words),
    'relations': len(pairs),
    'most_connected': most,
}
json.dump(words, open('words.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
json.dump(result, open('result.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
print('pages', len(pages), 'redirects', len(redirects))
print('dropped broken targets:', sorted(dropped))
print('directed links', total_links, 'distinct pairs', len(pairs))
print('most_connected', most, len(words[most]['sinonimos']) + len(words[most]['analogas']))
degs = sorted(((len(e['sinonimos']) + len(e['analogas']), w) for w, e in words.items()), reverse=True)[:8]
print('top degrees', degs)
print('temas', sorted({e['tema'] for e in words.values()}))


