import os, re, json, html
from urllib.parse import unquote
d = 'site'
words = {}
redirects = {}
for f in sorted(os.listdir(d)):
    if not f.endswith('.html'):
        continue
    raw = open(os.path.join(d, f), encoding='utf-8').read()
    m = re.search(r'http-equiv="refresh"[^>]*url=([^">]+)', raw)
    if m:
        redirects[f] = m.group(1)
        continue
    if f in ('index.html', 'sobre.html', 'contato.html'):
        continue
    t = re.search(r'<h1>(.*?)</h1>', raw)
    tema = re.search(r'class="tema">Tema: (.*?)<', raw)
    sec = {}
    for secm in re.finditer(r'<section id="(\w+)">(.*?)</section>', raw, re.S):
        sec[secm.group(1)] = [unquote(x) for x in re.findall(r'href="([^"]+\.html)"', secm.group(2))]
    words[f] = {
        'h1': html.unescape(t.group(1)) if t else f[:-5],
        'tema': html.unescape(tema.group(1)) if tema else None,
        'sinonimos': sec.get('sinonimos', []),
        'analogas': sec.get('analogas', []),
    }
print(len(words), 'word pages;', len(redirects), 'redirects')
broken = set()
for w in words.values():
    for t in w['sinonimos'] + w['analogas']:
        if t not in words:
            broken.add(t)
print('broken targets:', sorted(broken))
print(json.dumps(dict(list(words.items())[:3]), ensure_ascii=False, indent=1))
json.dump({'words': words, 'redirects': redirects}, open('tmp_parse.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)


